      <div className="chat-body">
        {messages.length === 0 && (
          <div className="chat-empty">
            {status === 'idle'
              ? 'Press Run Study to start the multi-agent simulation.'
              : 'Agent starting...'}
          </div>
        )}
        {messages.map((msg) => (
          <ChatMessage key={msg.id} msg={msg} />
        ))}
        {status === 'running' && (
          <div className="chat-typing">
            <span className="typing-dot" />
            <span className="typing-dot" />
            <span className="typing-dot" />
          </div>
        )}
        <div ref={bottomRef} />
      </div>
    </div>
  );
}

