import React, { useEffect, useRef } from 'react';
import './ChatPanel.css';

const AGENT_COLORS = ['', '#3b82f6', '#8b5cf6', '#06b6d4', '#f59e0b', '#f97316'];

function AgentTag({ role, subagentId }) {
  if (role === 'orchestrator') {
    return <span className="chat-tag orchestrator-tag">ORCHESTRATOR</span>;
  }
  if (role === 'subagent') {
    return (
      <span
        className="chat-tag subagent-tag"
        style={{ borderColor: AGENT_COLORS[subagentId] || '#64748b', color: AGENT_COLORS[subagentId] || '#94a3b8' }}
      >
        SUBAGENT {subagentId}
      </span>
    );
  }
  if (role === 'sim') {
    return (
      <span
        className="chat-tag sim-tag"
        style={{ borderColor: AGENT_COLORS[subagentId] || '#64748b' }}
      >
        SIM · AGENT {subagentId}
      </span>
    );
  }
  if (role === 'error') {
    return <span className="chat-tag error-tag">ERROR</span>;
  }
  return null;
}

function SimResultInline({ simulation }) {
  if (!simulation?.success) {
    return (
      <div className="sim-inline failed">
        <div className="sim-inline-header">
          <span className="sim-badge fail">FAILED</span>
        </div>
        <div className="sim-inline-error">{simulation?.error}</div>
      </div>
    );
  }
  const { results, requirements, passed, params } = simulation;
  const reqEntries = Object.entries(requirements || {});
  return (
    <div className={`sim-inline ${passed ? 'passed' : 'failed'}`}>
      <div className="sim-inline-header">
        <span className={`sim-badge ${passed ? 'pass' : 'fail'}`}>
          {passed ? 'PASSED' : 'FAILED'}
        </span>
        <span className="sim-inline-params">
          b={params.wingspan}m · AR={params.aspect_ratio} · {params.airfoil}
        </span>
        <span className="sim-inline-ld">L/D = {results.LD_ratio}</span>
      </div>
      <div className="sim-inline-reqs">
        {reqEntries.map(([key, r]) => (
          <span key={key} className={`req-chip ${r.passed ? 'ok' : 'ng'}`}>
            {r.passed ? '✓' : '✗'} {r.value}
          </span>
        ))}
      </div>
    </div>
  );
}

function ChatMessage({ msg }) {
  const time = new Date(msg.ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

  return (
    <div className={`chat-msg ${msg.role}`}>
      <div className="chat-msg-meta">
        <AgentTag role={msg.role} subagentId={msg.subagentId} />
        <span className="chat-msg-time">{time}</span>
      </div>

      {msg.role === 'sim' ? (
        <SimResultInline simulation={msg.simulation} />
      ) : (
        <div className="chat-msg-text">{msg.text}</div>
      )}
    </div>
  );
}

export default function ChatPanel({ messages, status }) {
  const bottomRef = useRef(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  return (
    <div className="chat-panel">
      <div className="panel-header">
        <span className="panel-title">Agent Activity</span>
        <span className="panel-count">{messages.length} messages</span>
      </div>

      <div className="chat-body">
        {messages.length === 0 && (
          <div className="chat-empty">
            {status === 'idle'
              ? 'Press Run Study to start the multi-agent simulation.'
              : 'Agent starting...'}
          </div>
        )}
        {messages.map((msg) => (
          <ChatMessage key={msg.id} msg={msg} />
        ))}
        {status === 'running' && (
          <div className="chat-typing">
            <span className="typing-dot" />
            <span className="typing-dot" />
            <span className="typing-dot" />
          </div>
        )}
        <div ref={bottomRef} />
      </div>
    </div>
  );
}

input.content:
.chat-panel {
  width: 38%;
  min-width: 300px;
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--border);
  background: var(--bg);
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-bottom: 1px solid var(--border);
  background: var(--bg2);
  flex-shrink: 0;
}

.panel-title {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--text2);
}

.panel-count {
  font-size: 11px;
  color: var(--text3);
}

.chat-body {
  flex: 1;
  overflow-y: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.chat-empty {
  color: var(--text3);
  font-size: 12px;
  text-align: center;
  margin-top: 40px;
  line-height: 1.7;
}

/* ── Message ──────────────────────────────────────────────────────────────── */
.chat-msg {
  border-radius: 8px;
  padding: 10px 12px;
  background: var(--bg2);
  border: 1px solid var(--border);
}

.chat-msg.error {
  border-color: var(--danger);
  background: rgba(239,68,68,0.08);
}

.chat-msg-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.chat-msg-time {
  font-size: 10px;
  color: var(--text3);
  margin-left: auto;
  font-family: var(--mono);
}

.chat-msg-text {
  font-size: 12px;
  color: var(--text2);
  white-space: pre-wrap;
  line-height: 1.6;
}

/* ── Tags ─────────────────────────────────────────────────────────────────── */
.chat-tag {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.6px;
  padding: 2px 7px;
  border-radius: 4px;
  border: 1px solid;
  font-family: var(--mono);
}

.orchestrator-tag {
  color: var(--accent);
  border-color: var(--accent);
  background: rgba(59,130,246,0.1);
}

.subagent-tag {
  background: rgba(255,255,255,0.04);
}

.sim-tag {
  background: rgba(255,255,255,0.04);
  color: var(--text3);
}

.error-tag {
  color: var(--danger);
  border-color: var(--danger);
  background: rgba(239,68,68,0.1);
}

/* ── Simulation inline result ─────────────────────────────────────────────── */
.sim-inline {
  border-radius: 6px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  background: var(--bg3);
}

.sim-inline.passed { border-color: rgba(34,197,94,0.35); }
.sim-inline.failed { border-color: rgba(239,68,68,0.35); }

.sim-inline-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
  flex-wrap: wrap;
}

.sim-badge {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 4px;
  letter-spacing: 0.5px;
}

.sim-badge.pass { background: rgba(34,197,94,0.2); color: var(--success); }
.sim-badge.fail { background: rgba(239,68,68,0.2); color: var(--danger); }

.sim-inline-params {
  font-size: 11px;
  color: var(--text3);
  font-family: var(--mono);
}

.sim-inline-ld {
  font-size: 12px;
  font-weight: 700;
  color: var(--text);
  font-family: var(--mono);
  margin-left: auto;
}

.sim-inline-error {
  font-size: 11px;
  color: var(--danger);
}

.sim-inline-reqs {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.req-chip {
  font-size: 10px;
  padding: 2px 6px;
  border-radius: 4px;
  font-family: var(--mono);
}

.req-chip.ok { background: rgba(34,197,94,0.1); color: var(--success); }
.req-chip.ng { background: rgba(239,68,68,0.1); color: var(--danger); }

/* ── Typing indicator ─────────────────────────────────────────────────────── */
.chat-typing {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 6px 4px;
}

.typing-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--text3);
  animation: typing 1s ease-in-out infinite;
}

.typing-dot:nth-child(2) { animation-delay: 0.2s; }
.typing-dot:nth-child(3) { animation-delay: 0.4s; }

@keyframes typing {
  0%, 100% { opacity: 0.3; transform: translateY(0); }
  50% { opacity: 1; transform: translateY(-3px); }
}

