60	function isInstalled() {
61	  try {
62	    if (fs.readFileSync(path.join(__dirname, 'dist', 'version'), 'utf-8').replace(/^v/, '') !== version) {
63	      return false;
64	    }
65	
66	    if (fs.readFileSync(path.join(__dirname, 'path.txt'), 'utf-8') !== platformPath) {
67	      return false;
68	    }
69	  } catch {
70	    return false;
71	  }
72	
73	  const electronPath = process.env.ELECTRON_OVERRIDE_DIST_PATH || path.join(__dirname, 'dist', platformPath);
74	
75	  return fs.existsSync(electronPath);
76	}
77	
78	// unzips and makes path.txt point at the correct executable
79	function extractFile(zipPath) {
80	  const distPath = process.env.ELECTRON_OVERRIDE_DIST_PATH || path.join(__dirname, 'dist');
