import Anthropic from '@anthropic-ai/sdk';
import { runSimulation } from './openvsp-mock.js';
import { simulationTool } from './tools.js';

const MAX_TOOL_ROUNDS = 5;

function buildSystemPrompt(id, focus) {
  return `You are Subagent ${id} in a parallel multi-agent UAV design study.

Mission — Fixed-wing surveillance drone:
• Payload: 1.5 kg camera/sensor package
• Cruise speed: 22 m/s
• Maximize L/D (Lift-to-Drag) ratio
• Wingspan HARD LIMIT: ≤ 2.0 m
• Longitudinally stable: static margin 5–25% MAC
• Directionally stable: Cnβ > 0
• Laterally stable: Clβ < 0

Your design focus: ${focus}

Workflow:
1. Call run_simulation with your initial parameters.
2. Analyze the result — identify what to improve (L/D too low? margin out of range?).
3. Run 1–2 refinement simulations.
4. Conclude with your best design and a brief engineering rationale.

Be concise. Cite specific numbers. One final recommendation only.`;
}

export async function runSubagent({ id, focus, initialParams, onProgress, signal }) {
  const client = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
  const simulations = [];

  const messages = [
    {
      role: 'user',
      content: `Start the design study. Try these initial parameters first:\n${JSON.stringify(initialParams, null, 2)}\n\nRun simulations, analyze results, and report your best design.`,
    },
  ];

  for (let round = 0; round < MAX_TOOL_ROUNDS; round++) {
    if (signal?.aborted) break;

    const response = await client.messages.create({
      model: 'claude-opus-4-8',
      max_tokens: 1024,
      system: buildSystemPrompt(id, focus),
      tools: [simulationTool],
      messages,
    });

    const toolUses = response.content.filter((b) => b.type === 'tool_use');
    const textBlocks = response.content.filter((b) => b.type === 'text');

    if (textBlocks.length > 0) {
      onProgress({
        type: 'subagent_text',
        subagentId: id,
        text: textBlocks.map((b) => b.text).join('\n'),
      });
    }

    if (response.stop_reason === 'end_turn' || toolUses.length === 0) {
      break;
    }

    messages.push({ role: 'assistant', content: response.content });

    const toolResults = [];
    for (const tu of toolUses) {
      if (tu.name === 'run_simulation') {
        const sim = runSimulation(tu.input);
        simulations.push(sim);

        onProgress({
          type: 'simulation_result',
          subagentId: id,
          simulation: sim,
        });

        toolResults.push({
          type: 'tool_result',
          tool_use_id: tu.id,
          content: JSON.stringify(sim, null, 2),
        });
      }
    }

    messages.push({ role: 'user', content: toolResults });
  }

  // Pick best passing simulation; fall back to last successful one
  const passing = simulations.filter((s) => s.success && s.passed);
  const successful = simulations.filter((s) => s.success);
  const bestSimulation =
    passing.sort((a, b) => b.results.LD_ratio - a.results.LD_ratio)[0] ||
    successful.sort((a, b) => b.results.LD_ratio - a.results.LD_ratio)[0] ||
    null;

  const finalText =
    messages
      .filter((m) => m.role === 'assistant')
      .flatMap((m) => (Array.isArray(m.content) ? m.content : [m.content]))
      .filter((b) => b?.type === 'text')
      .map((b) => b.text)
      .join('\n')
      .trim() || 'No analysis text.';

  return { id, focus, simulations, bestSimulation, finalAnalysis: finalText };
}

export const simulationTool = {
  name: 'run_simulation',
  description: `Run aerodynamic analysis for a fixed-wing UAV via OpenVSP (mock).
Returns: CL/CD breakdown, L/D ratio, static margin, Cnβ, wing geometry, power.
Mission: payload 1.5 kg, cruise 22 m/s, wingspan ≤ 2 m, maximize L/D, must be stable.
Tip: high AR reduces induced drag; tail volume coefficients drive stability margins.`,
  input_schema: {
    type: 'object',
    properties: {
      wingspan: {
        type: 'number',
        description: 'Wing span in meters. Hard limit: ≤ 2.0 m.',
      },
      aspect_ratio: {
        type: 'number',
        description: 'AR = b²/S. Range 6–13. Higher AR → lower induced drag but heavier structure.',
      },
      taper_ratio: {
        type: 'number',
        description: 'λ = c_tip/c_root. Range 0.3–0.9. Near-elliptical at λ≈0.45.',
      },
      sweep_angle_deg: {
        type: 'number',
        description: 'Quarter-chord sweep in degrees. Range 0–15. Low sweep preferred for low-speed UAVs.',
      },
      airfoil: {
        type: 'string',
        enum: ['NACA 2412', 'NACA 4412', 'Clark-Y'],
        description: 'Wing section. NACA 4412: more camber/lift. NACA 2412: lower drag at low CL. Clark-Y: classic glider.',
      },
      tail_volume_coeff_h: {
        type: 'number',
        description: 'Horizontal tail volume Vh = Sh·lh/(S·MAC). Controls pitch stability. Range 0.30–0.55.',
      },
      tail_volume_coeff_v: {
        type: 'number',
        description: 'Vertical tail volume Vv = Sv·lv/(S·b). Controls yaw stability. Range 0.030–0.070.',
      },
    },
    required: [
      'wingspan',
      'aspect_ratio',
      'taper_ratio',
      'sweep_angle_deg',
      'airfoil',
      'tail_volume_coeff_h',
      'tail_volume_coeff_v',
    ],
  },
};

