import React, { useEffect, useRef } from 'react';
import './ChatPanel.css';

const AGENT_COLORS = ['', '#3b82f6', '#8b5cf6', '#06b6d4', '#f59e0b', '#f97316'];

function AgentTag({ role, subagentId }) {
  if (role === 'orchestrator') {
    return <span className="chat-tag orchestrator-tag">ORCHESTRATOR</span>;
  }
  if (role === 'subagent') {
    return (
      <span
        className="chat-tag subagent-tag"
        style={{ borderColor: AGENT_COLORS[subagentId] || '#64748b', color: AGENT_COLORS[subagentId] || '#94a3b8' }}
      >
        SUBAGENT {subagentId}
      </span>
    );
  }
  if (role === 'sim') {
    return (
      <span
        className="chat-tag sim-tag"
        style={{ borderColor: AGENT_COLORS[subagentId] || '#64748b' }}
      >
        SIM · AGENT {subagentId}
      </span>
    );
  }
  if (role === 'error') {
    return <span className="chat-tag error-tag">ERROR</span>;
  }
  return null;
}

function SimResultInline({ simulation }) {
  if (!simulation?.success) {
    return (
      <div className="sim-inline failed">
        <div className="sim-inline-header">
          <span className="sim-badge fail">FAILED</span>
        </div>
        <div className="sim-inline-error">{simulation?.error}</div>
      </div>
    );
  }
  const { results, requirements, passed, params } = simulation;
  const reqEntries = Object.entries(requirements || {});
  return (
    <div className={`sim-inline ${passed ? 'passed' : 'failed'}`}>
      <div className="sim-inline-header">
        <span className={`sim-badge ${passed ? 'pass' : 'fail'}`}>
          {passed ? 'PASSED' : 'FAILED'}
        </span>
        <span className="sim-inline-params">
          b={params.wingspan}m · AR={params.aspect_ratio} · {params.airfoil}
        </span>
        <span className="sim-inline-ld">L/D = {results.LD_ratio}</span>
      </div>
      <div className="sim-inline-reqs">
        {reqEntries.map(([key, r]) => (
          <span key={key} className={`req-chip ${r.passed ? 'ok' : 'ng'}`}>
            {r.passed ? '✓' : '✗'} {r.value}
          </span>
        ))}
      </div>
    </div>
  );
}

function ChatMessage({ msg }) {
  const time = new Date(msg.ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

  return (
    <div className={`chat-msg ${msg.role}`}>
      <div className="chat-msg-meta">
        <AgentTag role={msg.role} subagentId={msg.subagentId} />
        <span className="chat-msg-time">{time}</span>
      </div>

      {msg.role === 'sim' ? (
        <SimResultInline simulation={msg.simulation} />
      ) : (
        <div className="chat-msg-text">{msg.text}</div>
      )}
    </div>
  );
}

export default function ChatPanel({ messages, status }) {
  const bottomRef = useRef(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  return (
    <div className="chat-panel">
      <div className="panel-header">
        <span className="panel-title">Agent Activity</span>
        <span className="panel-count">{messages.length} messages</span>
      </div>

      <div className="chat-body">
        {messages.length === 0 && (
          <div className="chat-empty">
            {status === 'idle'
              ? 'Press Run Study to start the multi-agent simulation.'
              : 'Agent starting...'}
          </div>
        )}
        {messages.map((msg) => (
          <ChatMessage key={msg.id} msg={msg} />
        ))}
        {status === 'running' && (
          <div className="chat-typing">
            <span className="typing-dot" />
            <span className="typing-dot" />
            <span className="typing-dot" />
          </div>
        )}
        <div ref={bottomRef} />
      </div>
    </div>
  );
}

import React from 'react';
import SimCard from './SimCard.jsx';
import { LDBarChart, DragPolarChart, WingspanLDScatter, RadarCompare } from './Charts.jsx';
import './ReportPanel.css';

function ChartBlock({ title, children }) {
  return (
    <div className="chart-block">
      <div className="chart-title">{title}</div>
      {children}
    </div>
  );
}

function EmptyState({ status }) {
  if (status === 'idle') {
    return (
      <div className="report-empty">
        <div className="report-empty-icon">✈</div>
        <div className="report-empty-title">Ready to design</div>
        <div className="report-empty-body">
          Press <strong>Run Study</strong> to launch 5 parallel AI subagents.<br />
          Each agent will test different wing configurations and report back.
        </div>
      </div>
    );
  }
  return (
    <div className="report-empty">
      <div className="report-empty-icon spin">⟳</div>
      <div className="report-empty-title">Simulations running...</div>
      <div className="report-empty-body">
        Results will appear here as subagents complete their studies.
      </div>
    </div>
  );
}

export default function ReportPanel({ report, simulations, subagentSummaries, status }) {
  const hasData = subagentSummaries.length > 0;
  const winnerId = report?.winner?.subagentId ?? null;

  if (!hasData && status !== 'done') {
    return (
      <div className="report-panel">
        <div className="panel-header">
          <span className="panel-title">Simulation Report</span>
        </div>
        <EmptyState status={status} />
      </div>
    );
  }

  const winnerSim = report?.winner ?? null;
  const passingCount = subagentSummaries.filter((s) => s.bestSimulation?.passed).length;

  return (
    <div className="report-panel">
      <div className="panel-header">
        <span className="panel-title">Simulation Report</span>
        <span className="panel-count">
          {passingCount}/{subagentSummaries.length} designs passed
        </span>
      </div>

      <div className="report-body">

        {/* ── Summary bar ──────────────────────────────────────────────────── */}
        {winnerSim && (
          <div className="winner-banner">
            <div className="winner-banner-left">
              <span className="winner-label">★ SELECTED DESIGN</span>
              <span className="winner-subagent">Agent {winnerSim.subagentId}</span>
            </div>
            <div className="winner-metrics">
              <div className="winner-metric">
                <span className="wm-val">{winnerSim.results?.LD_ratio}</span>
                <span className="wm-lbl">L/D</span>
              </div>
              <div className="winner-metric">
                <span className="wm-val">{winnerSim.params?.wingspan} m</span>
                <span className="wm-lbl">Wingspan</span>
              </div>
              <div className="winner-metric">
                <span className="wm-val">{winnerSim.results?.SM_pct}%</span>
                <span className="wm-lbl">Static Margin</span>
              </div>
              <div className="winner-metric">
                <span className="wm-val">{winnerSim.results?.power_W} W</span>
                <span className="wm-lbl">Cruise Power</span>
              </div>
              <div className="winner-metric">
                <span className="wm-val">{winnerSim.params?.airfoil}</span>
                <span className="wm-lbl">Airfoil</span>
              </div>
            </div>
          </div>
        )}

        {/* ── Charts ───────────────────────────────────────────────────────── */}
        <div className="charts-section">
          <div className="charts-row">
            <ChartBlock title="L/D Ratio — Design Comparison">
              <LDBarChart subagentSummaries={subagentSummaries} winnerId={winnerId} />
            </ChartBlock>
            <ChartBlock title="Wingspan vs L/D Trade-off">
              <WingspanLDScatter subagentSummaries={subagentSummaries} winnerId={winnerId} />
            </ChartBlock>
          </div>
          <div className="charts-row">
            <ChartBlock title={`Drag Polar — Winner (Agent ${winnerId ?? '?'})`}>
              <DragPolarChart winnerSim={winnerSim} />
            </ChartBlock>
            <ChartBlock title="Multi-Criteria Radar">
              <RadarCompare subagentSummaries={subagentSummaries} />
            </ChartBlock>
          </div>
        </div>

        {/* ── Synthesis ────────────────────────────────────────────────────── */}
        {report?.synthesis && (
          <div className="synthesis-block">
            <div className="synthesis-title">Chief Engineer Analysis</div>
            <div className="synthesis-text">{report.synthesis}</div>
          </div>
        )}

        {/* ── Design cards ─────────────────────────────────────────────────── */}
        <div className="cards-section-title">All Explored Designs</div>
        <div className="cards-grid">
          {subagentSummaries
            .slice()
            .sort((a, b) => {
              const aLD = a.bestSimulation?.results?.LD_ratio ?? -1;
              const bLD = b.bestSimulation?.results?.LD_ratio ?? -1;
              return bLD - aLD;
            })
            .map((s) => (
              <SimCard key={s.id} summary={s} isWinner={s.id === winnerId} />
            ))}
        </div>
      </div>
    </div>
  );
}

import React from 'react';
import './SimCard.css';

const AGENT_COLORS = ['', '#3b82f6', '#8b5cf6', '#06b6d4', '#f59e0b', '#f97316'];

function MetricRow({ label, value, unit = '' }) {
  return (
    <div className="sc-metric">
      <span className="sc-metric-label">{label}</span>
      <span className="sc-metric-value">{value}<span className="sc-metric-unit">{unit}</span></span>
    </div>
  );
}

function ReqRow({ label, req }) {
  if (!req) return null;
  return (
    <div className={`sc-req ${req.passed ? 'pass' : 'fail'}`}>
      <span className="sc-req-icon">{req.passed ? '✓' : '✗'}</span>
      <span className="sc-req-label">{label}</span>
      <span className="sc-req-value">{req.value}</span>
    </div>
  );
}

export default function SimCard({ summary, isWinner }) {
  const { id, focus, bestSimulation: sim, simCount } = summary;

  const color = AGENT_COLORS[id] || '#64748b';

  if (!sim?.success) {
    return (
      <div className="sim-card failed" style={{ borderTopColor: color }}>
        <div className="sc-header">
          <span className="sc-agent-label" style={{ color }}>AGENT {id}</span>
          <span className="sc-status-badge fail">NO VALID DESIGN</span>
        </div>
        <div className="sc-focus">{focus}</div>
        <div className="sc-error">{sim?.error || 'No successful simulation.'}</div>
      </div>
    );
  }

  const { results, requirements, params, passed } = sim;

  return (
    <div className={`sim-card ${passed ? 'passed' : 'failed'} ${isWinner ? 'winner' : ''}`}
      style={{ borderTopColor: isWinner ? '#22c55e' : color }}>

      <div className="sc-header">
        <span className="sc-agent-label" style={{ color: isWinner ? '#22c55e' : color }}>
          AGENT {id}
        </span>
        {isWinner && <span className="sc-winner-crown">★ WINNER</span>}
        <span className={`sc-status-badge ${passed ? 'pass' : 'fail'}`}>
          {passed ? 'ALL PASS' : 'REQ FAILED'}
        </span>
        <span className="sc-sim-count">{simCount} sim{simCount !== 1 ? 's' : ''}</span>
      </div>

      <div className="sc-focus">{focus}</div>

      <div className="sc-params">
        <span>b = {params.wingspan} m</span>
        <span>AR = {params.aspect_ratio}</span>
        <span>λ = {params.taper_ratio}</span>
        <span>Λ = {params.sweep_angle_deg}°</span>
        <span>{params.airfoil}</span>
        <span>Vh = {params.tail_volume_coeff_h}</span>
        <span>Vv = {params.tail_volume_coeff_v}</span>
      </div>

      <div className="sc-divider" />

      <div className="sc-metrics-grid">
        <MetricRow label="L/D" value={results.LD_ratio} />
        <MetricRow label="CL cruise" value={results.CL_cruise} />
        <MetricRow label="CD total" value={results.CD_total} />
        <MetricRow label="CD₀" value={results.CD_0} />
        <MetricRow label="CD_i" value={results.CD_induced} />
        <MetricRow label="Oswald e" value={results.e_oswald} />
        <MetricRow label="Static margin" value={results.SM_pct} unit="% MAC" />
        <MetricRow label="Cnβ" value={results.Cnbeta} />
        <MetricRow label="Power" value={results.power_W} unit=" W" />
        <MetricRow label="Wing area" value={results.S_wing_m2} unit=" m²" />
        <MetricRow label="MAC" value={results.MAC_m} unit=" m" />
        <MetricRow label="c_root" value={results.c_root_m} unit=" m" />
      </div>

      <div className="sc-divider" />

      <div className="sc-reqs">
        <ReqRow label="Wingspan" req={requirements?.wingspan} />
        <ReqRow label="L/D ≥ 12" req={requirements?.ld_ratio} />
        <ReqRow label="Long. stability" req={requirements?.long_stab} />
        <ReqRow label="Dir. stability" req={requirements?.dir_stab} />
        <ReqRow label="Lat. stability" req={requirements?.lat_stab} />
        <ReqRow label="CL feasibility" req={requirements?.cl_valid} />
      </div>
    </div>
  );
}

