.chat-msg {
  border-radius: 8px;
  padding: 10px 12px;
  background: var(--bg2);
  border: 1px solid var(--border);
}

.chat-msg.error {
  border-color: var(--danger);
  background: rgba(239,68,68,0.08);
}

.chat-msg-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.chat-msg-time {
  font-size: 10px;
  color: var(--text3);
  margin-left: auto;
  font-family: var(--mono);
}

.chat-msg-text {
  font-size: 12px;
  color: var(--text2);
  white-space: pre-wrap;
  line-height: 1.6;
}

/* ── Tags ─────────────────────────────────────────────────────────────────── */
.chat-tag {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.6px;
  padding: 2px 7px;
  border-radius: 4px;
  border: 1px solid;
  font-family: var(--mono);
}

.orchestrator-tag {
  color: var(--accent);
  border-color: var(--accent);
  background: rgba(59,130,246,0.1);
}

.subagent-tag {
  background: rgba(255,255,255,0.04);
}

.sim-tag {
  background: rgba(255,255,255,0.04);
  color: var(--text3);
}

.error-tag {
  color: var(--danger);
  border-color: var(--danger);
  background: rgba(239,68,68,0.1);
}

/* ── Simulation inline result ─────────────────────────────────────────────── */
.sim-inline {
  border-radius: 6px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  background: var(--bg3);
}

.sim-inline.passed { border-color: rgba(34,197,94,0.35); }
.sim-inline.failed { border-color: rgba(239,68,68,0.35); }

.sim-inline-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
  flex-wrap: wrap;
}

.sim-badge {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 4px;
  letter-spacing: 0.5px;
}

.sim-badge.pass { background: rgba(34,197,94,0.2); color: var(--success); }
.sim-badge.fail { background: rgba(239,68,68,0.2); color: var(--danger); }

.sim-inline-params {
  font-size: 11px;
  color: var(--text3);
  font-family: var(--mono);
}

.sim-inline-ld {
  font-size: 12px;
  font-weight: 700;
  color: var(--text);
  font-family: var(--mono);
  margin-left: auto;
}

.sim-inline-error {
  font-size: 11px;
  color: var(--danger);
}

.sim-inline-reqs {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.req-chip {
  font-size: 10px;
  padding: 2px 6px;
  border-radius: 4px;
  font-family: var(--mono);
}

.req-chip.ok { background: rgba(34,197,94,0.1); color: var(--success); }
.req-chip.ng { background: rgba(239,68,68,0.1); color: var(--danger); }

/* ── Typing indicator ─────────────────────────────────────────────────────── */
.chat-typing {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 6px 4px;
}

.typing-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--text3);
  animation: typing 1s ease-in-out infinite;
}

.typing-dot:nth-child(2) { animation-delay: 0.2s; }
.typing-dot:nth-child(3) { animation-delay: 0.4s; }

@keyframes typing {
  0%, 100% { opacity: 0.3; transform: translateY(0); }
  50% { opacity: 1; transform: translateY(-3px); }
}

