// Direct @electron/packager build — bypasses the forge plugin-vite finalize
// quirk that exits the process before the package is written. The production
// Vite bundles in .vite/ must already exist (run `npx electron-forge package`
// once, or it is produced by the prebuild step).

import path from 'node:path';
import * as pkg from '@electron/packager';

const packager = pkg.packager || pkg.default || pkg;
const root = process.cwd();

process.on('unhandledRejection', (e) => {
  console.error('UNHANDLED REJECTION:', e);
  process.exitCode = 1;
});

packager({
  dir: root,
  out: path.join(root, 'out'),
  platform: 'win32',
  arch: 'x64',
  asar: true,
  overwrite: true,
  name: 'openvsp-agent',
  appVersion: '1.0.0',
  ignore: [
    /^\/src($|\/)/,
    /^\/scripts($|\/)/,
    /^\/\.git($|\/)/,
    /^\/\.github($|\/)/,
    /^\/\.idea($|\/)/,
    /^\/\.claude($|\/)/,
    /^\/out($|\/)/,
    /^\/build\.log$/,
    /^\/\.env($|\.)/,
    /^\/forge\.config\.js$/,
    /^\/vite\..*\.config\.mjs$/,
    /^\/README\.md$/,
    /^\/future_work\.md$/,
  ],
})
  .then((paths) => {
    console.log('PACKAGED OK ->', paths);
  })
  .catch((err) => {
    console.error('PACKAGER ERROR:', err);
    process.exit(1);
  });

