const deps_dalpha = (2 * CL_alpha_w) / (Math.PI * aspect_ratio);          // wing downwash at tail
const NP = X_AC + ETA_H * tail_volume_coeff_h * (CL_alpha_h / CL_alpha_w) * (1 - deps_dalpha);
