1	// Aerodynamic model based on lifting-line theory + DATCOM empirical methods.
2	// Simulates OpenVSP analysis for a fixed-wing UAV at ISA sea-level conditions.
3	
4	const RHO = 1.225;       // kg/m³ — sea-level ISA air density
5	const G = 9.81;          // m/s²
6	const AIRFRAME_KG = 0.8; // structure + avionics + propulsion (excludes payload)
7	
8	// Defaults if the mission brief omits a value.
9	const MISSION_DEFAULTS = { payloadKg: 1.5, cruiseMs: 22, wingspanLimit: 2.0 };
10	
11	// Longitudinal-stability + trim-drag model constants.
12	const TAIL_AR = 4.5;     // assumed horizontal-tail aspect ratio (sets CLαh)
13	const ETA_H = 0.90;      // horizontal-tail efficiency (dynamic-pressure ratio)
14	const X_AC = 0.25;       // wing aerodynamic centre, fraction of MAC
15	const K_TRIM = 0.02;     // lumped trim-drag coefficient vs static margin
16	const CG_DEFAULT = 0.30; // CG (fraction of MAC) if the caller omits it
17	
18	const AIRFOILS = {
19	  'NACA 2412': { cl_alpha_2d: 6.28, cl_max: 1.30, cd_profile: 0.0058, cm_ac: -0.048 },
20	  'NACA 4412': { cl_alpha_2d: 6.30, cl_max: 1.55, cd_profile: 0.0070, cm_ac: -0.098 },
21	  'Clark-Y':   { cl_alpha_2d: 6.15, cl_max: 1.45, cd_profile: 0.0065, cm_ac: -0.082 },
22	};
23	
24	function r(val, dec) {
25	  return Math.round(val * 10 ** dec) / 10 ** dec;
26	}
27	
28	export function runSimulation(params, mission = {}) {
29	  const {
30	    wingspan,
31	    aspect_ratio,
32	    taper_ratio,
33	    sweep_angle_deg,
34	    airfoil,
35	    tail_volume_coeff_h,
36	    tail_volume_coeff_v,
37	    cg_position = CG_DEFAULT,
38	  } = params;
39	
40	  // Mission-driven operating point (parsed from the user's brief).
41	  const m = { ...MISSION_DEFAULTS, ...mission };
42	  const V_CRUISE = m.cruiseMs;
43	  const MTOW = AIRFRAME_KG + m.payloadKg;
44	  const spanLimit = m.wingspanLimit;
45	
46	  const foil = AIRFOILS[airfoil] || AIRFOILS['NACA 4412'];
47	
48	  // Wing geometry
49	  const S_wing = (wingspan ** 2) / aspect_ratio;
50	  const c_root = (2 * wingspan) / (aspect_ratio * (1 + taper_ratio));
51	  const c_tip = taper_ratio * c_root;
52	  const MAC = (2 / 3) * c_root * (1 + taper_ratio + taper_ratio ** 2) / (1 + taper_ratio);
53	
54	  // Cruise conditions
55	  const q = 0.5 * RHO * V_CRUISE ** 2;
56	  const W = MTOW * G;
57	  const CL_cruise = W / (q * S_wing);
58	
59	  if (CL_cruise > foil.cl_max * 0.90) {
60	    return {
61	      success: false,
62	      params,
63	      error: `Wing too small — CL_req=${r(CL_cruise, 3)} exceeds 90% of CLmax (${r(foil.cl_max * 0.9, 2)}). Increase wingspan or decrease AR.`,
64	    };
65	  }
66	  if (CL_cruise < 0.15) {
67	    return {
68	      success: false,
69	      params,
70	      error: `Wing oversized — CL_req=${r(CL_cruise, 3)} is too low for efficient cruise. Reduce wingspan.`,
71	    };
72	  }
73	
74	  // ── Longitudinal stability (computed before drag so trim drag can use SM) ──
75	  // NP = wing AC + horizontal-tail contribution. Vh already equals Sh·lh/(S·MAC),
76	  // so the tail's neutral-point shift is eta_h·Vh·(CLαh/CLαw)·(1 − dε/dα).
77	  const l_tail = wingspan * 0.55;
78	  const CL_alpha_w = (foil.cl_alpha_2d * aspect_ratio) / (aspect_ratio + 2); // Helmbold (3D wing)
79	  const CL_alpha_h = (6.28 * TAIL_AR) / (TAIL_AR + 2);                       // 3D tail lift slope
80	  const deps_dalpha = (2 * CL_alpha_w) / (Math.PI * aspect_ratio);          // wing downwash at tail
81	  const NP = X_AC + ETA_H * tail_volume_coeff_h * (CL_alpha_h / CL_alpha_w) * (1 - deps_dalpha);
82	  const CG = cg_position;          // controllable design input (fraction of MAC)
83	  const SM = NP - CG;
84	
85	  // Oswald efficiency (Raymer empirical, corrected for sweep)
86	  const sweep_rad = (sweep_angle_deg * Math.PI) / 180;
87	  const e_raw = 1.78 * (1 - 0.045 * aspect_ratio ** 0.68) - 0.64;
88	  const e = Math.min(Math.max(e_raw * (1 - 0.08 * Math.sin(sweep_rad) ** 2), 0.5), 0.95);
89	
90	  // Drag breakdown
91	  const CD_induced = CL_cruise ** 2 / (Math.PI * aspect_ratio * e);
92	
93	  // Parasitic: wing profile + fuselage + tail
94	  const CD_fus = (0.003 * 0.085) / S_wing;            // fuselage wetted area ~0.085 m²
95	  const CD_tail = foil.cd_profile * (0.12 + tail_volume_coeff_h * 0.12);
96	  const CD_sweep = 0.0002 * (sweep_angle_deg / 5);
97	  const CD_0 = foil.cd_profile + CD_fus + CD_tail + CD_sweep;
98	
99	  // Trim drag: holding the CG ahead of the NP needs tail download → extra drag,
100	  // so a larger static margin (more forward CG) costs L/D.
101	  const CD_trim = K_TRIM * SM ** 2;
102	  const CD_total = CD_0 + CD_induced + CD_trim;
103	
104	  const LD_ratio = CL_cruise / CD_total;
105	  const Thrust = W / LD_ratio;
106	  const Power_W = Thrust * V_CRUISE;
107	
108	  // Directional stability (Cnβ > 0 required)
109	  const S_tail_v = (tail_volume_coeff_v * S_wing * wingspan) / l_tail;
110	  const Cnbeta = (S_tail_v * l_tail) / (S_wing * wingspan) - 0.0015;
111	
112	  // Lateral stability (dihedral effect) — simplified
113	  const Clbeta = -0.05 - 0.003 * aspect_ratio + 0.02 * (sweep_angle_deg / 5);
114	
115	  // Requirements
116	  const req = {
117	    wingspan:   { passed: wingspan <= spanLimit,    value: `${r(wingspan,2)} m`,          limit: `≤ ${spanLimit} m` },
118	    ld_ratio:   { passed: LD_ratio >= 12.0,         value: r(LD_ratio, 2).toString(),     limit: '≥ 12.0' },
119	    long_stab:  { passed: SM >= 0.05 && SM <= 0.25, value: `SM = ${r(SM*100,1)}% MAC`,   limit: '5%–25% MAC' },
120	    dir_stab:   { passed: Cnbeta > 0,               value: `Cnβ = ${r(Cnbeta,4)}`,       limit: '> 0' },
121	    lat_stab:   { passed: Clbeta < 0,               value: `Clβ = ${r(Clbeta,4)}`,       limit: '< 0' },
122	    cl_valid:   { passed: CL_cruise >= 0.2,         value: `CL = ${r(CL_cruise,3)}`,     limit: '≥ 0.2' },
123	  };
124	  const passed = Object.values(req).every((r) => r.passed);
125	
126	  return {
127	    success: true,
128	    params: { ...params, cg_position: CG },
129	    results: {
130	      CL_cruise:  r(CL_cruise, 4),
131	      CD_0:       r(CD_0, 5),
132	      CD_induced: r(CD_induced, 5),
133	      CD_trim:    r(CD_trim, 5),
134	      CD_total:   r(CD_total, 5),
