*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:        #0f1117;
  --bg2:       #161b27;
  --bg3:       #1e2537;
  --border:    #2d3548;
  --accent:    #3b82f6;
  --success:   #22c55e;
  --danger:    #ef4444;
  --warn:      #f59e0b;
  --text:      #f1f5f9;
  --text2:     #94a3b8;
  --text3:     #64748b;
  --mono:      'JetBrains Mono', 'Fira Code', monospace;

  --c1: #3b82f6;
  --c2: #8b5cf6;
  --c3: #06b6d4;
  --c4: #f59e0b;
  --c5: #f97316;
}

html, body, #root {
  height: 100%;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 13px;
  line-height: 1.5;
  overflow: hidden;
}

/* ── Layout ───────────────────────────────────────────────────────────────── */
.app {
  display: flex;
  flex-direction: column;
  height: 100vh;
}

.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  height: 52px;
  border-bottom: 1px solid var(--border);
  background: var(--bg2);
  flex-shrink: 0;
}

.app-header-left {
  display: flex;
  align-items: center;
  gap: 12px;
}

.app-logo {
  width: 26px;
  height: 26px;
  background: var(--accent);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
}

.app-title {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.2px;
}

.app-subtitle {
  font-size: 11px;
  color: var(--text3);
}

.app-body {
  display: flex;
  flex: 1;
  overflow: hidden;
}

/* ── Run Button ───────────────────────────────────────────────────────────── */
.btn-run {
  padding: 7px 18px;
  border-radius: 6px;
  border: none;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, opacity 0.15s;
}

.btn-run.idle {
  background: var(--accent);
  color: #fff;
}
.btn-run.idle:hover { background: #2563eb; }

.btn-run.running {
  background: var(--danger);
  color: #fff;
}
.btn-run.running:hover { background: #dc2626; }

.btn-run.done {
  background: var(--bg3);
  color: var(--text2);
  border: 1px solid var(--border);
}
.btn-run.done:hover { background: var(--border); }

/* ── Status pill ──────────────────────────────────────────────────────────── */
.status-pill {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--text3);
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--text3);
}
.status-dot.running {
  background: var(--success);
  animation: pulse 1.2s ease-in-out infinite;
}
.status-dot.done { background: var(--success); }
.status-dot.error { background: var(--danger); }

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}

/* ── Scrollbar ────────────────────────────────────────────────────────────── */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--text3); }

/* ── Header icon button + key warning ─────────────────────────────────────── */
.btn-icon {
  width: 30px;
  height: 30px;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--bg3);
  color: var(--text2);
  font-size: 15px;
  cursor: pointer;
